import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"First-time setup","description":"","frontmatter":{},"headers":[],"relativePath":"setup.md","filePath":"setup.md","lastUpdated":1792860039000}'),r={name:"setup.md"};function i(n,e,p,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="first-time-setup" tabindex="-1">First-time setup <a class="header-anchor" href="#first-time-setup" aria-label="Permalink to &quot;First-time setup&quot;">​</a></h1><p>This page walks through the setup window that opens the first time you start MeetCue. It takes about five minutes, most of it spent creating API keys.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You need an account with one speech recognition provider and one language model provider. MeetCue doesn&#39;t pick them for you: the setup window shows prices side by side and you choose.</p><table tabindex="0"><thead><tr><th>Task</th><th>Providers in this release</th></tr></thead><tbody><tr><td>Speech recognition</td><td>Soniox, Deepgram</td></tr><tr><td>Question detection and hints</td><td>Anthropic, any OpenAI-compatible API</td></tr></tbody></table><p>Detection and hints can use different models, and even different providers. Detection is a simple yes/no task, so a cheaper model is usually enough.</p><h2 id="step-1-language" tabindex="-1">Step 1: Language <a class="header-anchor" href="#step-1-language" aria-label="Permalink to &quot;Step 1: Language&quot;">​</a></h2><p>Choose <strong>English</strong> or <strong>简体中文</strong>, or let MeetCue follow the Windows display language. You can change it later in <strong>Settings › General</strong>; every window switches immediately.</p><h2 id="step-2-audio" tabindex="-1">Step 2: Audio <a class="header-anchor" href="#step-2-audio" aria-label="Permalink to &quot;Step 2: Audio&quot;">​</a></h2><p>MeetCue listens to two sources:</p><ul><li><strong>Microphone (you)</strong>: the microphone you speak into. <em>System default</em> follows the device chosen in Windows Sound settings.</li><li><strong>Other participants</strong>: everything played through your default output device, which is how meeting apps play other people&#39;s voices.</li></ul><p>Click <strong>Test levels</strong>, play a video and say something. Both level bars should move. If the system sound bar stays flat, see <a href="/meetcue/troubleshooting/audio">Audio and devices</a>.</p><div class="tip custom-block"><p class="custom-block-title">Use headphones</p><p>With speakers, your microphone also picks up the other participants. MeetCue filters most of this echo, but headphones give the cleanest result.</p></div><h2 id="step-3-models-and-prices" tabindex="-1">Step 3: Models and prices <a class="header-anchor" href="#step-3-models-and-prices" aria-label="Permalink to &quot;Step 3: Models and prices&quot;">​</a></h2><p>For each of the three tasks, pick a model from the list. Each line shows the model&#39;s price (per audio hour, or per million input and output tokens), an estimated cost per hour of meeting, and the measured latency once you have run the latency probe. The list is sorted by estimated cost; <strong>Cheapest</strong> and <strong>Fastest</strong> mark the best figures. You choose each model yourself, and you can&#39;t continue until all three are chosen.</p><p>Prices are not built into MeetCue. It downloads the <a href="/meetcue/reference/pricing">price reference</a>, which is checked against each provider&#39;s official pricing page, and keeps the last copy for offline use; <strong>Update prices</strong> fetches it again. A model the list doesn&#39;t cover links to the provider&#39;s official pricing page instead of showing a figure.</p><h2 id="step-4-api-keys" tabindex="-1">Step 4: API keys <a class="header-anchor" href="#step-4-api-keys" aria-label="Permalink to &quot;Step 4: API keys&quot;">​</a></h2><p>Paste the key for each provider you chose and click <strong>Save and verify</strong>. MeetCue stores keys only in Windows Credential Manager; they never appear in the settings file or the logs.</p><p>How to get each key is described in <a href="/meetcue/guide/providers">Providers and keys</a>:</p><ul><li><a href="/meetcue/guide/providers#soniox">Soniox</a></li><li><a href="/meetcue/guide/providers#deepgram">Deepgram</a></li><li><a href="/meetcue/guide/providers#anthropic">Anthropic</a></li><li><a href="/meetcue/guide/providers#openai-compatible-apis">OpenAI-compatible APIs</a></li></ul><p>If verification fails, the message shows an error code such as <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>. Click <strong>See the fix</strong> to open the matching section.</p><h2 id="step-5-latency-probe" tabindex="-1">Step 5: Latency probe <a class="header-anchor" href="#step-5-latency-probe" aria-label="Permalink to &quot;Step 5: Latency probe&quot;">​</a></h2><p>The probe measures how fast each provider responds from your network and picks the fastest endpoint for each one. It costs a few cents with keys, or nothing if you only measure the network. You can skip it and run it later from <strong>Settings › Providers &amp; cost</strong>. See <a href="/meetcue/guide/latency">Latency probe</a>.</p><h2 id="step-6-done" tabindex="-1">Step 6: Done <a class="header-anchor" href="#step-6-done" aria-label="Permalink to &quot;Step 6: Done&quot;">​</a></h2><p>Press <code>Ctrl+Alt+Space</code> when your next meeting starts. To see MeetCue in action first, try the <a href="/meetcue/quick-start">five-minute tour</a>.</p>',25)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
